T("Adding & subtracting","Story problems","Adding and taking away to 100",function(){var a=R(12,60),b=R(5,39),t=R(0,2);if(t===0)return Q("A shop has "+a+" red balloons and "+b+" blue balloons."+sm("How many balloons in all?"),a+b,a+" + "+b+" = "+(a+b)+".");if(t===1)return Q("One jar has "+(a+b)+" marbles. Another has "+a+"."+sm("How many more are in the first jar?"),b,(a+b)+" "+M+" "+a+" = "+b+".");return Q("A baker makes "+(a+b)+" buns and sells "+b+"."+sm("How many are left?"),a,(a+b)+" "+M+" "+b+" = "+a+".");});
T("Number sense","Comparing numbers","Which one is greater?",function(){var a=R(11,199),b;do{b=a+pick([-1,1])*pick([1,10])*R(1,9);}while(b===a||b<10);return Q("Which is greater: "+a+" or "+b+"?"+sm("Type the greater number"),Math.max(a,b),"Compare the biggest place first. "+Math.max(a,b)+" is greater.");});
T("Number sense","10 more, 10 less","Jumping by tens",function(){var a=R(15,185);if(R(0,1))return Q("What is 10 more than "+a+"?",a+10,"The tens digit goes up by one: "+(a+10)+".");return Q("What is 10 less than "+a+"?",a-10,"The tens digit goes down by one: "+(a-10)+".");});
