T("Multiplying & dividing","Times 2, 5 and 10","Easy times tables",function(){var a=pick([2,5,10]),b=R(1,10);return Q(a+" "+X+" "+b,a*b,"Count by "+a+"s, "+b+" times: "+(a*b)+".");});
