T("Data & probability","Tally marks","Count in groups of five",function(){var g=R(1,4),e=R(0,4);return Q("A tally shows "+g+" group"+(g>1?"s":"")+" of five and "+e+" more."+sm("What number is that?"),5*g+e,"Count by 5s: "+(5*g)+". Add "+e+": "+(5*g+e)+".");});
T("Data & probability","Picture graphs","Each picture stands for 2",function(){var k=R(1,9),e=pick(PICS);return Q("Each "+e+" stands for 2 children.<br>"+P(pics(e,k))+sm("How many children is that?"),2*k,"Count by 2s for each picture: "+(2*k)+".");});
