T("Multiplying & dividing","Division facts","Sharing equally",function(){var a=R(2,12),b=R(2,12);return Q((a*b)+" "+D+" "+a,b,"Think: "+a+" "+X+" what = "+(a*b)+"? The answer is "+b+".");});
