grade(5);
T("Number sense","3-digit × 2-digit","Like 246 × 35",function(){var a=R(101,499),b=R(11,49);return Q(a+" "+X+" "+b,a*b,a+" "+X+" "+(Math.floor(b/10)*10)+" = "+com(a*Math.floor(b/10)*10)+", plus "+a+" "+X+" "+(b%10)+" = "+com(a*(b%10))+". Total "+com(a*b)+".");});
T("Number sense","Dividing big numbers","Like 2,358 ÷ 6",function(){var b=R(3,9),q=R(112,999);return Q(com(b*q)+" "+D+" "+b,q,b+" "+X+" "+q+" = "+com(b*q)+".");});
T("Number sense","Biggest shared factor","Greatest common factor",function(){var g=R(2,12),m=coprime(1,6);return Q("Greatest common factor of "+(g*m[0])+" and "+(g*m[1]),g,"Both divide by "+g+", and nothing bigger divides both.");});
T("Number sense","Smallest shared multiple","Lowest common multiple",function(){var a=R(2,12),b;do{b=R(2,12);}while(b===a);var l=a*b/gcd(a,b);return Q("Lowest common multiple of "+a+" and "+b,l,"List the multiples of each. The first one they share is "+l+".");});
