T("Fractions & decimals","Adding decimals","Like 3.4 + 2.75",function(){var a=R(10,999),b=R(10,999);return Q((a/100)+" + "+(b/100),dec((a+b)/100),"Line up the decimal points: "+dec((a+b)/100)+".");});
T("Fractions & decimals","Subtracting decimals","Like 8.5 − 2.36",function(){var a=R(200,999),b=R(10,a);return Q((a/100)+" "+M+" "+(b/100),dec((a-b)/100),"Line up the decimal points: "+dec((a-b)/100)+".");});
T("Fractions & decimals","Times 10, 100, 1000","Move the decimal point",function(){var a=R(101,9999),t=pick([10,100,1000]);return Q((a/100)+" "+X+" "+com(t),dec(a*t/100),"Move the decimal point "+(String(t).length-1)+" places right: "+dec(a*t/100)+".");});
T("Fractions & decimals","Decimal times a whole","Like 3.6 × 4",function(){var a=R(11,99),b=R(2,9);return Q((a/10)+" "+X+" "+b,dec(a*b/10,1),a+" "+X+" "+b+" = "+(a*b)+", then put one decimal place back: "+dec(a*b/10,1)+".");});
T("Fractions & decimals","Rounding decimals","To the nearest tenth",function(){var v=R(1000,9999);if(v%10===5)v++;var a=Math.round(v/10)/10;return Q("Round "+(v/100)+sm("to the nearest tenth"),a,"Look at the hundredths digit: 5 or more rounds up. Answer "+a+".");});
T("Fractions & decimals","Fraction of a number","Like ¾ of 20",function(){var d=pick([2,3,4,5,6,8,10]),nn=R(1,d-1),k=R(2,12);return Q(nn+"/"+d+" of "+(d*k),nn*k,(d*k)+" "+D+" "+d+" = "+k+", then "+k+" "+X+" "+nn+" = "+(nn*k)+".");});
T("Fractions & decimals","Adding fractions","Different bottom numbers",function(){var d1=pick([2,3,4,5,6]),d2;do{d2=pick([2,3,4,5,6,8]);}while(d2===d1);var a=R(1,d1-1),b=R(1,d2-1),t=a*d2+b*d1,dd=d1*d2;return Q(a+"/"+d1+" + "+b+"/"+d2,t/dd,"Use the same bottom number "+dd+": "+(a*d2)+"/"+dd+" + "+(b*d1)+"/"+dd+" = "+t+"/"+dd+(fr(t,dd)!==t+"/"+dd?" = "+fr(t,dd):"")+".",fr(t,dd));});
T("Fractions & decimals","Simplest form","Like 6/8 = 3/4",function(){var m=coprime(1,9),a=Math.min(m[0],m[1]),b=Math.max(m[0],m[1]),g=R(2,6);return Q("Write "+(a*g)+"/"+(b*g)+" in simplest form",a/b,"Divide top and bottom by "+g+": "+a+"/"+b+".",a+"/"+b,true);});
T("Fractions & decimals","Mixed numbers","Like 2 1/3 = ?/3",function(){var w=R(1,6),d=R(2,8),a=R(1,d-1);return Q(w+" "+a+"/"+d+" = ?/"+d,w*d+a,w+" "+X+" "+d+" = "+(w*d)+", plus "+a+" = "+(w*d+a)+".");});
T("Measurement","Volume of a box","Length × width × height",function(){var a=R(2,10),b=R(2,10),c=R(2,10);return Q("Box "+a+" by "+b+" by "+c+sm("Volume?"),a*b*c,a+" "+X+" "+b+" "+X+" "+c+" = "+(a*b*c)+".");});
T("Geometry & angles","Angles in a triangle","They add to 180°",function(){var a=R(20,100),b=R(20,150-a);return Q("A triangle has angles "+a+"° and "+b+"°."+sm("What is the third angle?"),180-a-b,"180 "+M+" "+a+" "+M+" "+b+" = "+(180-a-b)+"°.");});
T("Measurement","Metric units","cm, m, mL and L",function(){var k=R(11,99);var t=R(0,2);if(t===0)return Q("How many centimetres in "+(k/10)+" metres?",k*10,(k/10)+" "+X+" 100 = "+(k*10)+".");if(t===1)return Q("How many millilitres in "+(k/10)+" litres?",k*100,(k/10)+" "+X+" 1,000 = "+com(k*100)+".");return Q("How many metres in "+(k*10)+" centimetres?",k/10,(k*10)+" "+D+" 100 = "+(k/10)+".");});
T("Data & probability","Average (mean)","Add them, then share",function(){var k=R(3,5),a=[],s=0;for(var i=0;i<k-1;i++){a.push(R(1,20));s+=a[i];}var l=R(1,10);l+=(k-(s+l)%k)%k;a.push(l);s+=l;return Q("Mean of "+a.join(", "),s/k,"Add them: "+s+". Divide by "+k+": "+(s/k)+".");});
