T("Number sense","Place value to a million","What a digit is worth",function(){var v,pl,dg,N=["ones","tens","hundreds","thousands","ten thousands","hundred thousands"];do{v=R(100000,999999);pl=R(1,5);dg=Math.floor(v/Math.pow(10,pl))%10;}while(dg===0);return Q("In "+com(v)+", what is the value of the digit in the "+N[pl]+" place?",dg*Math.pow(10,pl),"The digit is "+dg+". In the "+N[pl]+" place it is worth "+com(dg*Math.pow(10,pl))+".");});
