T("Number sense","Rounding big numbers","To the nearest hundred or thousand",function(){var t=pick([100,1000]),v=R(10000,99999);if(v%t===t/2)v++;var a=Math.round(v/t)*t;return Q("Round "+com(v)+sm("to the nearest "+(t===100?"hundred":"thousand")),a,"Look at the digit to the right of the "+(t===100?"hundreds":"thousands")+" place. 5 or more rounds up. Answer "+com(a)+".");});
T("Fractions & decimals","Comparing fractions","Which one is bigger?",function(){function f(){var d=pick([2,3,4,5,6,8]),k;do{k=R(1,d-1);}while(gcd(k,d)!==1);return [k,d];}var a,b;do{a=f();b=f();}while(a[1]===b[1]||a[0]*b[1]===b[0]*a[1]);var big=a[0]*b[1]>b[0]*a[1]?a:b,dd=a[1]*b[1];return Q("Which is bigger: "+a[0]+"/"+a[1]+" or "+b[0]+"/"+b[1]+"?"+sm("Type the bigger fraction"),big[0]/big[1],"Use the same bottom number "+dd+": "+(a[0]*b[1])+"/"+dd+" and "+(b[0]*a[1])+"/"+dd+". The bigger one is "+big[0]+"/"+big[1]+".",big[0]+"/"+big[1],true);});
T("Fractions & decimals","Subtracting fractions","Different bottom numbers",function(){var d1,d2,a,b,t;do{d1=pick([2,3,4,5,6]);d2=pick([2,3,4,5,6,8]);a=R(1,d1-1);b=R(1,d2-1);t=a*d2-b*d1;}while(d1===d2||t<=0);var dd=d1*d2;return Q(a+"/"+d1+" "+M+" "+b+"/"+d2,t/dd,"Use the same bottom number "+dd+": "+(a*d2)+"/"+dd+" "+M+" "+(b*d1)+"/"+dd+" = "+t+"/"+dd+(fr(t,dd)!==t+"/"+dd?" = "+fr(t,dd):"")+".");});
