T("Algebraic expressions","Value of an expression","Like n + 7 when n = 5",function(){var v=R(2,12),a=R(2,9),b=R(1,15),t=R(0,2);if(t===0)return Q("n + "+b+sm("What is it worth when n = "+v+"?"),v+b,"Put "+v+" in place of n: "+v+" + "+b+" = "+(v+b)+".");if(t===1)return Q(a+" "+X+" n"+sm("What is it worth when n = "+v+"?"),a*v,"Put "+v+" in place of n: "+a+" "+X+" "+v+" = "+(a*v)+".");return Q(a+" "+X+" n + "+b+sm("What is it worth when n = "+v+"?"),a*v+b,"Multiply first: "+a+" "+X+" "+v+" = "+(a*v)+". Then add "+b+": "+(a*v+b)+".");});
T("Equations & inequalities","Find the missing number","Like n + 8 = 15",function(){var v=R(2,20),a=R(2,12),t=R(0,3);if(t===0)return Q("n + "+a+" = "+(v+a)+sm("What is n?"),v,"Undo the adding: "+(v+a)+" "+M+" "+a+" = "+v+".");if(t===1)return Q("n "+M+" "+a+" = "+v+sm("What is n?"),v+a,"Undo the taking away: "+v+" + "+a+" = "+(v+a)+".");if(t===2)return Q(a+" "+X+" n = "+(a*v)+sm("What is n?"),v,"Undo the multiplying: "+(a*v)+" "+D+" "+a+" = "+v+".");return Q("n "+D+" "+a+" = "+v+sm("What is n?"),a*v,"Undo the dividing: "+v+" "+X+" "+a+" = "+(a*v)+".");});
