T("Patterns & linear relationships","Pattern rules","Find a later number",function(){var a=R(1,12),d=R(2,9),k=R(6,12);return Q("Start at "+a+" and add "+d+" each time."+sm("What is number "+k+" in the pattern?"),a+(k-1)*d,"You add "+d+" a total of "+(k-1)+" times: "+a+" + "+(k-1)+" "+X+" "+d+" = "+(a+(k-1)*d)+".");});
