T("Number sense","Order of operations","Brackets, times, then plus",function(){var a=R(2,12),b=R(2,9),c=R(2,9),d=R(1,9);var t=R(0,2);if(t===0)return Q(a+" + "+b+" "+X+" "+c+" "+M+" "+d,a+b*c-d,"Multiply first: "+(b*c)+". Then "+a+" + "+(b*c)+" "+M+" "+d+" = "+(a+b*c-d)+".");if(t===1)return Q("("+a+" + "+b+") "+X+" "+c,(a+b)*c,"Brackets first: "+(a+b)+", then "+X+" "+c+" = "+((a+b)*c)+".");return Q(a+sup(2)+" + "+b+" "+X+" "+c,a*a+b*c,"Powers first: "+(a*a)+". Then "+b+" "+X+" "+c+" = "+(b*c)+". Total "+(a*a+b*c)+".");});
T("Number sense","Factors and multiples","GCF and LCM",function(){if(Math.random()<.5){var g=R(2,15),m=coprime(1,7);return Q("Greatest common factor of "+(g*m[0])+" and "+(g*m[1]),g,"Both divide by "+g+", and nothing bigger divides both.");}var a=R(3,15),b;do{b=R(3,15);}while(b===a);var l=a*b/gcd(a,b);return Q("Lowest common multiple of "+a+" and "+b,l,"The first number in both times tables is "+l+".");});
T("Fractions & decimals","Multiplying fractions","Top × top, bottom × bottom",function(){var d1=R(2,9),d2=R(2,9),a=R(1,d1-1),b=R(1,d2-1);return Q(a+"/"+d1+" "+X+" "+b+"/"+d2,a*b/(d1*d2),"Tops: "+(a*b)+". Bottoms: "+(d1*d2)+". Simplified: "+fr(a*b,d1*d2)+".",fr(a*b,d1*d2));});
T("Fractions & decimals","Dividing fractions","Flip the second, then multiply",function(){var d1=R(2,9),d2=R(2,9),a=R(1,d1-1),b=R(1,d2-1);return Q(a+"/"+d1+" "+D+" "+b+"/"+d2,a*d2/(d1*b),"Flip the second: "+a+"/"+d1+" "+X+" "+d2+"/"+b+" = "+fr(a*d2,d1*b)+".",fr(a*d2,d1*b));});
