T("Ratios, rates & proportions","Ratios","Like 2 : 3 = 8 : ?",function(){var a=R(1,9),b=R(1,9),k=R(2,9);return Q(a+" : "+b+" = "+(a*k)+" : ?",b*k,a+" became "+(a*k)+" (times "+k+"), so "+b+" "+X+" "+k+" = "+(b*k)+".");});
T("Ratios, rates & proportions","Price for one","Unit rates",function(){var k=R(2,9),c=R(2,15);return Q(k+" notebooks cost $"+(k*c)+"."+sm("How many dollars for one?"),c,(k*c)+" "+D+" "+k+" = "+c+".");});
