T("Equations & inequalities","One-step equations","Find the missing number",function(){var x=R(1,20),a=R(2,12),t=R(0,2);if(t===0)return Q("x + "+a+" = "+(x+a)+sm("What is x?"),x,(x+a)+" "+M+" "+a+" = "+x+".");if(t===1)return Q("x "+M+" "+a+" = "+x+sm("What is x?"),x+a,x+" + "+a+" = "+(x+a)+".");return Q(a+"x = "+(a*x)+sm("What is x?"),x,(a*x)+" "+D+" "+a+" = "+x+".");});
