T("Measurement","Volume of a box","Length × width × height",function(){var a=R(2,12),b=R(2,12),c=R(2,12);return Q("Box "+a+" by "+b+" by "+c+sm("Volume?"),a*b*c,a+" "+X+" "+b+" "+X+" "+c+" = "+com(a*b*c)+".");});
T("Data & probability","Mean, median and range","Three ways to sum up data",function(){var a=[],i;for(i=0;i<5;i++)a.push(R(1,30));var s=a.slice().sort(function(x,y){return x-y;});var t=R(0,2);if(t===0)return Q("Median of "+a.join(", "),s[2],"In order: "+s.join(", ")+". The middle one is "+s[2]+".");if(t===1)return Q("Range of "+a.join(", "),s[4]-s[0],"Biggest "+M+" smallest: "+s[4]+" "+M+" "+s[0]+" = "+(s[4]-s[0])+".");var sum=a[0]+a[1]+a[2]+a[3];var l=R(1,10);l+=(5-(sum+l)%5)%5;a[4]=l;sum+=l;return Q("Mean of "+a.join(", "),sum/5,"Add them: "+sum+". Divide by 5: "+(sum/5)+".");});

