T("Measurement","Area of a trapezoid","Parallel sides and height",function(){var a=R(3,12),b=R(a+1,18),h=R(2,10)*2;return Q("A trapezoid has parallel sides of "+a+" cm and "+b+" cm, and a height of "+h+" cm"+sm("What is its area in cm²?"),(a+b)*h/2,"Area = (a + b) "+D+" 2 "+X+" h: ("+a+" + "+b+") "+D+" 2 "+X+" "+h+" = "+((a+b)*h/2)+" cm².");});
