T("Data & probability","Median and mode","Middle and most common",function(){var m=R(5,15),o;do{o=[R(1,20),R(1,20),R(1,20)];}while(o.indexOf(m)>-1||o[0]===o[1]||o[0]===o[2]||o[1]===o[2]);var L=[m,m].concat(o),S=L.slice().sort(function(a,b){return a-b;}),show=shuffle(L.slice()).join(", ");if(R(0,1))return Q(show+sm("What is the median?"),S[2],"Put them in order: "+S.join(", ")+". The middle one is "+S[2]+".");return Q(show+sm("What is the mode?"),m,"The mode is the number that appears most often: "+m+".");});
