T("Number sense","Rational or irrational","Count the irrational numbers",function(){var k=R(1,3),ir=shuffle(["√2","√3","√5","√6","√7","√8","√10","√11"]).slice(0,k),ra=shuffle(["1/2",M+"3","0.3","√9","√16","0.75","2/3","√25",M+"1.5","7","√49","4/5"]).slice(0,4-k),all=shuffle(ir.concat(ra));return Q(all.join(" &nbsp; ")+sm("How many of these numbers are irrational?"),k,"A square root is irrational unless the number under it is a perfect square. Fractions, whole numbers and decimals that end are rational. Irrational here: "+ir.join(", ")+".");});
T("Fractions & decimals","Fractions, decimals and percents","Like 135% as a decimal",function(){var t=R(0,2);if(t===0){var pc=pick([135,250,104,0.5,12.5,7,62.5,180,0.25,45]);return Q(pc+"%"+sm("Write it as a decimal"),pc/100,"Divide by 100: "+pc+" "+D+" 100 = "+(pc/100)+".");}if(t===1){var f=pick([[3,8],[1,8],[5,8],[7,8],[3,5],[7,20],[9,25],[3,2],[5,4],[1,40]]);var v=f[0]/f[1]*100;return Q(f[0]+"/"+f[1]+sm("Write it as a percent (number only)"),v,"Divide, then multiply by 100: "+f[0]+" "+D+" "+f[1]+" = "+(f[0]/f[1])+", which is "+v+"%.");}var d=pick([0.35,1.2,0.08,0.625,2.5,0.045,0.9,1.05]);return Q(d+sm("Write it as a percent (number only)"),dec(d*100,1),"Multiply by 100: "+d+" "+X+" 100 = "+dec(d*100,1)+"%.");});
T("Number sense","Order of operations with powers","Like 4 + 3² × 2",function(){var a=R(2,12),b=R(2,6),c=R(2,5);if(R(0,1))return Q(a+" + "+b+"² "+X+" "+c,a+b*b*c,"Power first: "+b+"² = "+(b*b)+". Then multiply: "+(b*b)+" "+X+" "+c+" = "+(b*b*c)+". Then add "+a+": "+(a+b*b*c)+".");var s=R(2,5),t=R(1,4);return Q("("+s+" + "+t+")² "+M+" "+a,(s+t)*(s+t)-a,"Brackets first: "+(s+t)+". Then the power: "+((s+t)*(s+t))+". Then subtract "+a+": "+n((s+t)*(s+t)-a)+".");});
T("Number sense","Integer sums","Like −7 − (−4) + 9",function(){var a=nz(-12,12),b=nz(-12,12),c=nz(-12,12);return Q(n(a)+" "+M+" "+p(b)+" + "+p(c),a-b+c,"Subtracting a number is the same as adding its opposite: "+n(a)+" + "+p(-b)+" = "+n(a-b)+". Then add "+p(c)+": "+n(a-b+c)+".");});
T("Fractions & decimals","Adding and subtracting fractions","Like 2/3 + 1/4",function(){var ds=pick([[2,3],[3,4],[2,5],[3,5],[4,5],[2,7],[3,8],[5,6],[4,9]]),b=ds[0],d=ds[1],a=R(1,b-1)||1,c=R(1,d-1),add=R(0,1)===1;if(!add&&a*d<=c*b)add=true;var num=add?a*d+c*b:a*d-c*b,den=b*d,s=fr(num,den);return Q(a+"/"+b+" "+(add?"+":M)+" "+c+"/"+d+sm("Answer as a fraction in simplest form, like 5/6"),num/den,"Use the common denominator "+den+": "+(a*d)+"/"+den+" "+(add?"+":M)+" "+(c*b)+"/"+den+" = "+num+"/"+den+(s!==num+"/"+den?" = "+s:"")+".",s,true);});
T("Fractions & decimals","Multiplying and dividing fractions","Like 3/4 ÷ 2/5",function(){var a=R(1,5),b=R(a+1,8),c=R(1,5),d=R(c+1,9),mul=R(0,1)===1,num=mul?a*c:a*d,den=mul?b*d:b*c,s=fr(num,den);return Q(a+"/"+b+" "+(mul?X:D)+" "+c+"/"+d+sm("Answer as a fraction in simplest form"),num/den,(mul?"Multiply the tops and multiply the bottoms: ":"Flip the second fraction and multiply: "+a+"/"+b+" "+X+" "+d+"/"+c+" = ")+num+"/"+den+(s!==num+"/"+den?" = "+s:"")+".",s,true);});
