T("Exponents & roots","Square roots to the nearest whole number","Like √50 ≈ 7",function(){var r=R(2,14),v=r*r+R(1,2*r),a=Math.round(Math.sqrt(v)),lo=r*r,hi=(r+1)*(r+1);return Q("Estimate √"+v+" to the nearest whole number.",a,v+" is between "+lo+" and "+hi+", so √"+v+" is between "+r+" and "+(r+1)+". "+v+" is closer to "+(a===r?lo:hi)+", so √"+v+" ≈ "+a+".");});
