T("Exponents & logs","Exponential equations","Like 2ˣ = 32",function(){var b=pick([2,3,5]),k=b===2?R(2,10):(b===3?R(2,5):R(2,4));return Q(b+"ˣ = "+com(Math.pow(b,k))+sm("What is x?"),k,b+" multiplied by itself "+k+" times is "+com(Math.pow(b,k))+".");});
T("Exponents & logs","Fraction powers","Like 27^(2/3)",function(){var d=pick([2,3]),k=d===2?R(2,6):R(2,4),m=R(1,d===2?3:2);return Q(Math.pow(k,d)+"^("+m+"/"+d+")",Math.pow(k,m),"Take the "+(d===2?"square":"cube")+" root first: "+k+". Then raise to the power "+m+": "+Math.pow(k,m)+".");});
T("Financial literacy","Compound interest","Growing year after year",function(){var P=R(1,10)*1000,r=pick([5,10,20]);return Q("$"+com(P)+" grows "+r+"% a year for 2 years."+sm("Final amount in dollars?"),dec(P*(100+r)*(100+r)/10000),"Multiply by "+(1+r/100)+" twice: "+dec(P*(100+r)*(100+r)/10000)+".");});
T("Sequences","Arithmetic sequences","Find a term",function(){var a=R(-10,20),d=nz(-6,9),k=R(8,30);var s=[a,a+d,a+2*d,a+3*d].map(n).join(", ");return Q(s+", …"+sm("Term number "+k+"?"),a+(k-1)*d,"First term "+n(a)+", step "+n(d)+". Term "+k+" = "+n(a)+" + "+(k-1)+" "+X+" "+p(d)+" = "+n(a+(k-1)*d)+".");});
