T("Sequences","Arithmetic series","Add up the terms",function(){var a=R(1,10),d=R(1,6),k=R(5,20);var s=k*(2*a+(k-1)*d)/2;return Q(a+" + "+(a+d)+" + "+(a+2*d)+" + …"+sm("Sum of the first "+k+" terms?"),s,"Sum = n "+D+" 2 "+X+" (first + last) = "+k+" "+D+" 2 "+X+" ("+a+" + "+(a+(k-1)*d)+") = "+s+".");});
T("Functions","Function inside a function","f(g(x))",function(){var a=nz(-5,5),b=R(-9,9),k=R(-4,4);var g=k*k,v=a*g+b;return Q("f(x) = "+poly([[a,"x"],[b,""]])+", g(x) = x²"+sm("f(g("+n(k)+"))?"),v,"g("+n(k)+") = "+g+". Then f("+g+") = "+n(a*g)+" "+pm(b)+" = "+n(v)+".");});
T("Functions","Inverse functions","Undo the rule",function(){var a=nz(2,6),b=R(-9,9),x=R(-6,8);return Q("f(x) = "+poly([[a,"x"],[b,""]])+sm("f⁻¹("+n(a*x+b)+")?"),x,"Solve "+poly([[a,"x"],[b,""]])+" = "+n(a*x+b)+": x = "+n(x)+".");});
T("Functions","Absolute value equations","Two answers",function(){var a=R(-9,9),b=R(1,12);return Q("|x "+pm(-a)+"| = "+b+sm("Bigger value of x?"),a+b,"x "+pm(-a)+" = "+b+" or "+M+b+". So x = "+n(a+b)+" or "+n(a-b)+".");});
T("Functions","Remainder theorem","Plug in to find the remainder",function(){var b=R(-4,4),c=R(-6,6),d=R(-9,9),k=nz(-2,3);var v=k*k*k+b*k*k+c*k+d;return Q("("+poly([[1,"x³"],[b,"x²"],[c,"x"],[d,""]])+") "+D+" (x "+pm(-k)+")"+sm("What is the remainder?"),v,"The remainder is the value at x = "+n(k)+": "+n(v)+".");});
T("Functions","How many solutions","Using the discriminant",function(){var a=R(1,3),b=R(-8,8),t=R(0,2),c;if(t===1){b=2*R(-4,4);a=1;c=b*b/4;}else{c=R(-6,6);}var dsc=b*b-4*a*c;var ans=dsc>0?2:(dsc===0?1:0);return Q(poly([[a,"x²"],[b,"x"],[c,""]])+" = 0"+sm("How many real solutions: 0, 1 or 2?"),ans,"b² "+M+" 4ac = "+n(dsc)+". "+(dsc>0?"Positive means 2":(dsc===0?"Zero means 1":"Negative means 0"))+".");});
T("Trigonometry","Exact values","sin, cos and tan",function(){var v=pick([["sin 30°",.5],["cos 60°",.5],["tan 45°",1],["sin 90°",1],["cos 0°",1],["cos 90°",0],["sin 0°",0],["cos 180°",-1],["sin 270°",-1],["sin 150°",.5],["cos 120°",-.5],["tan 135°",-1],["sin 210°",-.5],["cos 360°",1],["tan 180°",0]]);return Q(v[0],v[1],"From the unit circle, "+v[0]+" = "+n(v[1])+".");});
