T("Exponents & logs","Negative exponents","Like 2⁻³ = 1/8",function(){var b=pick([2,3,4,5,10]),e=R(1,3),d=Math.pow(b,e),s="1/"+d;return Q(b+sup(-e)+sm("Answer as a fraction"),1/d,"A negative exponent means one over the positive power: 1/"+b+sup(e)+" = "+s+".",s,true);});
T("Exponents & logs","Exponential growth","Doubling and tripling",function(){var P=pick([5,10,20,50,100,200]),k=pick([2,3]),t=R(2,5);return Q("A population of "+P+" "+(k===2?"doubles":"triples")+" every hour."+sm("How many are there after "+t+" hours?"),P*Math.pow(k,t),"Multiply by "+k+" once for each hour: "+P+" "+X+" "+k+sup(t)+" = "+com(P*Math.pow(k,t))+".");});
T("Exponents & logs","Half-life","Halving again and again",function(){var k=R(1,5),A=pick([1,2,5,10])*Math.pow(2,5),h=pick([2,5,10,30]);return Q("A sample of "+A+" g has a half-life of "+h+" years."+sm("How many grams are left after "+(h*k)+" years?"),A/Math.pow(2,k),(h*k)+" years is "+k+" half-li"+(k===1?"fe":"ves")+". Halve "+A+" "+k+" time"+(k===1?"":"s")+": "+(A/Math.pow(2,k))+".");});
T("Algebraic expressions","Expanding (ax + b)(cx + d)","Brackets with numbers in front of x",function(){var a=R(2,5),b=nz(-7,7),c=R(1,5),d=nz(-7,7),full=poly([[a*c,"x²"],[a*d+b*c,"x"],[b*d,""]]);if(R(0,1))return Q("("+poly([[a,"x"],[b,""]])+")("+poly([[c,"x"],[d,""]])+")"+sm("After expanding, what number is in front of x²?"),a*c,"Multiply the first terms: "+a+"x "+X+" "+(c===1?"":c)+"x = "+(a*c)+"x². Full answer: "+full+".");return Q("("+poly([[a,"x"],[b,""]])+")("+poly([[c,"x"],[d,""]])+")"+sm("After expanding, what number is in front of x?"),a*d+b*c,"Outside plus inside: "+n(a*d)+"x and "+n(b*c)+"x make "+n(a*d+b*c)+"x. Full answer: "+full+".");});
T("Algebraic expressions","Adding radicals","Like 3√5 + 2√5",function(){var k=pick([2,3,5,6,7]),a=R(2,9),b=R(1,9);if(R(0,1))return Q(a+"√"+k+" + "+b+"√"+k+" = ?√"+k+sm("What number goes in front?"),a+b,"The roots are the same, so add the numbers in front: "+a+" + "+b+" = "+(a+b)+".");var big=a+b;return Q(big+"√"+k+" "+M+" "+b+"√"+k+" = ?√"+k+sm("What number goes in front?"),a,"The roots are the same, so subtract the numbers in front: "+big+" "+M+" "+b+" = "+a+".");});
T("Algebraic expressions","Multiplying radicals","√a × √b = √(ab)",function(){var p1=pick([[2,8,4],[3,12,6],[2,18,6],[5,20,10],[3,27,9],[2,32,8],[6,24,12],[2,50,10],[7,28,14],[5,45,15]]);return Q("√"+p1[0]+" "+X+" √"+p1[1],p1[2],"Multiply under the root: √"+(p1[0]*p1[1])+" = "+p1[2]+".");});
T("Functions","Evaluating functions","Find f(x) for a given x",function(){var a=nz(-3,3),b=R(-6,6),c=R(-9,9),x=R(-4,5);return Q("f(x) = "+poly([[a,"x²"],[b,"x"],[c,""]])+sm("What is f("+n(x)+")?"),a*x*x+b*x+c,"Put "+n(x)+" in place of x: "+n(a)+"("+n(x)+")² "+pm(b)+"("+n(x)+") "+pm(c)+" = "+n(a*x*x+b*x+c)+".");});
