T("Functions","Solving f(x) = k","Work back from the output",function(){var m=nz(-6,6),b=R(-10,10),x=R(-8,8);return Q("f(x) = "+poly([[m,"x"],[b,""]])+sm("For what x is f(x) = "+n(m*x+b)+"?"),x,"Solve "+poly([[m,"x"],[b,""]])+" = "+n(m*x+b)+". x = "+n(x)+".");});
T("Transformations","Shifts of a graph","y = f(x − h) + k",function(){var a=R(-6,6),b=R(-6,6),h=nz(-6,6),k=nz(-6,6);if(R(0,1))return Q("The point ("+n(a)+", "+n(b)+") is on y = f(x). The graph becomes y = f(x "+pm(-h)+") "+pm(k)+"."+sm("What is the new x-coordinate of the point?"),a+h,"f(x "+pm(-h)+") moves the graph "+Math.abs(h)+(h>0?" right":" left")+". New x = "+n(a+h)+".");return Q("The point ("+n(a)+", "+n(b)+") is on y = f(x). The graph becomes y = f(x "+pm(-h)+") "+pm(k)+"."+sm("What is the new y-coordinate of the point?"),b+k,"Adding "+n(k)+" outside moves the graph "+Math.abs(k)+(k>0?" up":" down")+". New y = "+n(b+k)+".");});
T("Transformations","Stretches of a graph","y = a f(x)",function(){var a=pick([2,3,4,5]),x=R(-6,6),y=nz(-6,6);return Q("The point ("+n(x)+", "+n(y)+") is on y = f(x). The graph becomes y = "+a+"f(x)."+sm("What is the new y-coordinate of the point?"),a*y,"Every y value is multiplied by "+a+": "+a+" "+X+" "+p(y)+" = "+n(a*y)+". The x value stays the same.");});
T("Transformations","Reflections","y = −f(x) and y = f(−x)",function(){var x=nz(-8,8),y=nz(-8,8);if(R(0,1))return Q("The point ("+n(x)+", "+n(y)+") is on y = f(x). The graph becomes y = "+M+"f(x)."+sm("What is the new y-coordinate of the point?"),-y,"y = "+M+"f(x) flips the graph over the x-axis. The y value changes sign: "+n(-y)+".");return Q("The point ("+n(x)+", "+n(y)+") is on y = f(x). The graph becomes y = f("+M+"x)."+sm("What is the new x-coordinate of the point?"),-x,"y = f("+M+"x) flips the graph over the y-axis. The x value changes sign: "+n(-x)+".");});
T("Sequences","Recursive sequences","Each term comes from the one before",function(){var a=R(1,9);if(R(0,1)){var d=nz(-6,9);return Q("t₁ = "+a+" and each term is the one before "+(d>0?"plus ":"minus ")+Math.abs(d)+"."+sm("What is t₅?"),a+4*d,"List them: "+[a,a+d,a+2*d,a+3*d,a+4*d].map(n).join(", ")+".");}var r=pick([2,3]);return Q("t₁ = "+a+" and each term is "+r+" times the one before."+sm("What is t₄?"),a*r*r*r,"List them: "+[a,a*r,a*r*r,a*r*r*r].join(", ")+".");});
