T("Trigonometry","Amplitude and period","y = a sin(kx)",function(){var a=R(2,9),k=pick([1,2,3,4,5,6,9,10,12]);if(R(0,1))return Q("y = "+a+" sin("+(k===1?"":k)+"x)"+sm("What is the amplitude?"),a,"The amplitude is the number in front of sin: "+a+".");return Q("y = "+a+" sin("+(k===1?"":k)+"x), with x in degrees"+sm("What is the period in degrees?"),360/k,"Period = 360 "+D+" k = 360 "+D+" "+k+" = "+(360/k)+"°.");});
T("Trigonometry","Degrees to radians","Multiply by π ÷ 180",function(){var d=pick([30,45,60,90,120,135,150,180,210,225,240,270,300,315,330,360]),s=fr(d,180);return Q(d+"° = ?π radians"+sm("What goes in front of π? Type a fraction or a whole number"),d/180,d+" "+D+" 180 = "+s+", so "+d+"° = "+(s==="1"?"":s)+"π radians.",s,true);});
