T("Series & logs","Geometric series","Add up the terms",function(){var a=R(1,5),r=pick([2,3]),k=r===2?R(3,8):R(3,5);var s=a*(Math.pow(r,k)-1)/(r-1),t=[];for(var i=0;i<Math.min(k,4);i++)t.push(a*Math.pow(r,i));return Q(t.join(" + ")+(k>4?" + …":"")+sm("Sum of the first "+k+" terms?"),s,"Sum = a(rⁿ "+M+" 1) "+D+" (r "+M+" 1) = "+a+"("+com(Math.pow(r,k))+" "+M+" 1) "+D+" "+(r-1)+" = "+com(s)+".");});
