T("Series & logs","Log laws","Adding and subtracting logs",function(){var b=pick([2,3]),i=R(1,5),j=R(1,4);var sub=b===2?"₂":"₃";if(Math.random()<.5)return Q("log"+sub+" "+Math.pow(b,i)+" + log"+sub+" "+Math.pow(b,j),i+j,i+" + "+j+" = "+(i+j)+".");return Q("log"+sub+" "+Math.pow(b,i+j)+" "+M+" log"+sub+" "+Math.pow(b,j),i,(i+j)+" "+M+" "+j+" = "+i+".");});
